amily\', \'com.apple.filesystems.apfs\', \'com.apple.iokit.CoreAnalyticsFamily\', \'com.apple.iokit.IOAVFamily\', \'com.apple.iokit.IOAudio2Family\', \'com.apple.iokit.IOCECFamily\', \'com.apple.iokit.IOCryptoAcceleratorFamily\', \'com.apple.iokit.IOGPUFamily\', \'com.apple.iokit.IOHDCPFamily\', \'com.apple.iokit.IOMobileGraphicsFamily\', \'com.apple.iokit.IOReportFamily\', \'com.apple.iokit.IOSlowAdaptiveClockingFamily\', \'com.apple.iokit.IOStorageFamily\', \'com.apple.iokit.IOSurface\', \'com.apple.kec.Libm\', \'com.apple.kec.corecrypto\', \'com.apple.kext.AppleMatch\', \'com.apple.kext.CoreTrust\', \'com.apple.security.AppleImage4\', \'com.apple.security.sandbox\', \'com.apple.iokit.IOHIDFamily\', \'com.apple.iokit.IOHIDEventDriver\', \'com.apple.iokit.IOUSBDeviceFamily\', \'com.apple.driver.AppleUSBXDCI\', \'com.apple.driver.AppleUSBDeviceMux\', \'com.apple.iokit.IOUSBHostFamily\', \'com.apple.driver.usb.AppleUSBXHCI\', \'com.apple.driver.usb.AppleUSBHub\', \'com.apple.driver.usb.AppleUSBHostCompositeDevice\', \'com.apple.driver.usb.IOUSBHostHIDDevice\', \'com.apple.iokit.IOUSBMassStorageDriver\', \'com.apple.iokit.IOSCSIArchitectureModelFamily\', \'com.apple.iokit.IOSCSIBlockCommandsDevice\', \'!com.apple.driver.AppleOnboardSerial\', \'!com.apple.driver.AppleSMC\']\nDEVICE_ROOTS = PROFILE_ROOTS + [\'com.apple.iokit.IOUSBDeviceFamily\', \'com.apple.driver.AppleUSBXDCI\', \'com.apple.driver.AppleUSBDeviceMux\']\nUSB_BEGIN = \'# USB device mode: the native SM8550 subclass\'\nUSB_END = \'# The VPU:\'\nUSB_BLOCK_SHA256 = \'934fa8786b78981247bdf0bdee66e803832ac7f8baa5711956899c57f46e8b0e\'\ndef check_usb_block(t):\n if t.count(USB_BEGIN)!=1 or t.count(USB_END)!=1:raise ValueError(\'USB block missing/ambiguous (removal already applied?)\')\n block=t[t.index(USB_BEGIN):t.index(USB_END)]\n if hashlib.sha256(block.encode()).hexdigest()!=USB_BLOCK_SHA256:raise ValueError(\'pinned USB builder block changed\')\ndef once(text,old,new):\n if text.count(old)!=1:raise ValueError(\'nonunique/missing anchor: \'+old[:100])\n return text.replace(old,new,1)\ndef span(text,start,end,new=\'\'):\n if text.count(start)!=1 or text.count(end)!=1:raise ValueError(\'nonunique span\')\n a=text.index(start);b=text.index(end,a);return text[:a]+new+text[b:]\ndef transform_driver(t):\n t=once(t,\'#include "OriginalUsbXhciABI.h"\\n\',\'\')\n t=span(t,"// Host mode: Apple\'s xHCI driver",\'namespace {\\nbool bringUp()\')\n t=once(t,\'enum Role {kRoleNone, kRoleDevice, kRoleHost};\',\'enum Role {kRoleNone, kRoleDevice};\')\n t=once(t,\'bool gForceHost;\\nRegion gGlobals, gXhciRegs;\\nQcomDwc3Nub *gDeviceNub, *gHostNub;\\nQcomDwc3Xhci *gHost;\',\'QcomDwc3Nub *gDeviceNub;\')\n t=once(t,\'    if (!gRoleLock) return;\',\'    if (!gRoleLock || (role != kRoleNone && role != kRoleDevice)) return;\')\n t=once(t,\'            else if (gUcsi.partner == kUcsiPartnerUfp || gUcsi.partner == kUcsiPartnerCableUfp) role = kRoleHost;\\n\',\'\')\n t=once(t,\'    wantRole(gForceHost ? kRoleHost : role);\',\'    wantRole(role);\')\n t=span(t,\'void forceHostThread(\', \'void leaveRole(\')\n t=span(t,\'    } else if (role == kRoleHost && gHostNub) {\',\'// qmp_combo_typec_switch_set\',\'    }\\n}\\n// Device-only: the XDCI reset owns the core mode; cable removal powers the device stack down.\\n\')\n t=span(t,\'void enterHost() {\',\'void enterRole(\')\n t=span(t,\'    setCoreRole(role);\',\'void roleThread(\',\'\'\'    QcomDwc3Nub::route(gDeviceNub);\n    IOService::getResourceService()->setProperty("AppleUSBCableType", "USBHost");\n    native_usb_stats[20] = (uint32_t)gController->cable(true);\n}\n\'\'\')\n t=span(t,\'        while (gRoleWanted == gRoleApplied) {\',\'        const int role = gRoleWanted;\', \'        while (gRoleWanted == gRoleApplied) IOLockSleep(gRoleLock, &gRoleWanted, THREAD_UNINT);\\n\')\n t=once(t,\'        if (role == kRoleHost) gDeviceStackAllowed = false;\\n\',\'\')\n t=once(t,\'extern "C" void qcom_dwc3_host_load(int result) {native_usb_stats[46] = (u