e original diversities\')")\n t=once(t,", ROOT / f\'scripts/usb-xhci-{BUILD}.json\'",\'\')\n t=once(t,"require(all(usb_entries), f\'{usb_vt}: at least the {len(usb_slots)} AppleUSBXDCI entries\')", "require(len(usb_entries) == len(usb_slots) and all(usb_entries), f\'{usb_vt}: all {len(usb_slots)} required AppleUSBXDCI entries\')")\n t=once(t,"usb_found = object_symbols(usb_raw)","usb_found = object_symbols(usb_raw)\\nrequire(not any(\'xhci\' in n.lower() for n, _, _ in usb_found), \'device-only object has no XHCI symbols\')")\n t=once(t,"for name, va in sorted(usb_bindings.items()):", "require(not any(\'xhci\' in n.lower() for n in usb_bindings), \'device-only bindings have no XHCI symbols\')\\nfor name, va in sorted(usb_bindings.items()):")\n ast.parse(t)\n return t\n\ndef transform_board(t):\n marker=\'["os_overrides"."ipados-27.0.1-24A446"."kernel"."prelink"]\'\n if t.count(marker)!=1:raise ValueError(\'27 prelink override missing or ambiguous\')\n data=tomllib.loads(t);actual=data[\'os_overrides\'][\'ipados-27.0.1-24A446\'][\'kernel\'][\'prelink\'][\'roots\']\n if actual!=OLD_ROOTS:raise ValueError(\'unexpected roots; refuse partial or previously transformed override\')\n pos=t.index(marker);end=t.find(chr(10)+\'[\',pos+len(marker));end=len(t) if end<0 else end\n section=t[pos:end];section=once(section,\'"roots" = \'+json.dumps(OLD_ROOTS),\'"roots" = \'+json.dumps(DEVICE_ROOTS))\n result=t[:pos]+section+t[end:];assert tomllib.loads(result)[\'os_overrides\'][\'ipados-27.0.1-24A446\'][\'kernel\'][\'prelink\'][\'roots\']==DEVICE_ROOTS\n return result\n\ndef apply(device_root,driver_root):\n device=pathlib.Path(device_root).resolve();driver=pathlib.Path(driver_root).resolve()\n items=[(driver/\'QcomDwc3.cpp\',transform_driver,\'dfa0cf5fd612e3a23f8006f7bf7d78b6ec19b06efbd207de24b71b1afaa78648\'),\n        (device/\'package/UsbProbe.cpp\',transform_probe,\'c8b7f630a33c67deee481d21033756dd1a533cb32dd1161f0939a8f16df223bd\'),\n        (device/\'scripts/build-gop-legacy-